# db_cache_middleware.rb
# Ruby database connection pool with query result caching
# Designed to sit behind nginx reverse proxy with X-Forwarded-For support

require 'digest'
require 'json'
require 'socket'
require 'thread'

module DbProxy
  class QueryCache
    def initialize(max_size: 1024)
      @cache = {}
      @mutex = Mutex.new
      @max_size = max_size
      @hits = 0
      @misses = 0
    end

    def get(key)
      @mutex.synchronize do
        entry = @cache[key]
        if entry && !expired?(entry)
          @hits += 1
          entry[:value]
        else
          @cache.delete(key) if entry
          @misses += 1
          nil
        end
      end
    end

    def set(key, value, ttl: 300)
      @mutex.synchronize do
        evict_oldest if @cache.size >= @max_size
        @cache[key] = { value: value, expires_at: Time.now.to_f + ttl, created_at: Time.now.to_f }
      end
    end

    def invalidate(pattern)
      @mutex.synchronize do
        @cache.delete_if { |k, _| k.include?(pattern) }
      end
    end

    private

    def expired?(entry)
      Time.now.to_f > entry[:expires_at]
    end

    def evict_oldest
      oldest_key = @cache.min_by { |_, v| v[:created_at] }&.first
      @cache.delete(oldest_key) if oldest_key
    end
  end

  class ConnectionContext
    attr_reader :tenant_id, :role, :source_ip

    def initialize(headers:)
      @tenant_id = extract_tenant(headers)
      @role = extract_role(headers)
      @source_ip = extract_source_ip(headers)
    end

    private

    def extract_tenant(headers)
      headers['X-Tenant-ID'] || 'default'
    end

    def extract_role(headers)
      headers['X-User-Role'] || 'anonymous'
    end

    def extract_source_ip(headers)
      forwarded = headers['X-Forwarded-For']
      if forwarded
        forwarded.split(',').first.strip
      else
        headers['REMOTE_ADDR'] || '127.0.0.1'
      end
    end
  end

  class QueryProcessor
    ROLE_HIERARCHY = {
      'admin' => 3,
      'manager' => 2,
      'user' => 1,
      'anonymous' => 0
    }.freeze

    def initialize(cache:)
      @cache = cache
    end

    def execute(query, context:)
      normalized = normalize_query(query)
      cache_key = compute_cache_key(normalized, context)

      cached_result = @cache.get(cache_key)
      return cached_result if cached_result

      result = perform_query(normalized, context)
      @cache.set(cache_key, result, ttl: compute_ttl(normalized))
      result
    end

    private

    def normalize_query(query)
      query.gsub(/\s+/, ' ').strip.downcase
    end

    def compute_cache_key(query, context)
      # Cache key incorporates query, tenant, AND role for proper isolation
      components = [
        context.tenant_id,
        context.role,
        query_fingerprint(query)
      ]
      Digest::SHA256.hexdigest(components.join('|'))
    end

    def query_fingerprint(query)
      # Replace literal values with placeholders for better cache hit rates
      normalized = query.gsub(/'[^']*'/, '?')
                       .gsub(/\b\d+\b/, '?')
      Digest::SHA256.hexdigest(normalized)
    end

    def compute_ttl(query)
      if query.include?('select')
        300
      else
        0
      end
    end

    def perform_query(query, context)
      # Simulate DB query with role-based row filtering
      base_results = simulate_db_fetch(query)
      apply_row_level_security(base_results, context)
    end

    def simulate_db_fetch(query)
      # Simulated database results
      if query.include?('users')
        [
          { id: 1, name: 'Alice', email: 'alice@corp.com', salary: 95000, ssn: '123-45-6789' },
          { id: 2, name: 'Bob', email: 'bob@corp.com', salary: 85000, ssn: '987-65-4321' },
          { id: 3, name: 'Charlie', email: 'charlie@corp.com', salary: 105000, ssn: '456-78-9012' }
        ]
      else
        [{ id: 1, data: 'public_info' }]
      end
    end

    def apply_row_level_security(results, context)
      role_level = ROLE_HIERARCHY[context.role] || 0

      results.map do |row|
        filtered = row.dup
        if role_level < 3  # non-admin
          filtered.delete(:ssn)
        end
        if role_level < 2  # non-manager
          filtered.delete(:salary)
        end
        filtered
      end
    end
  end

  class Server
    def initialize(port: 8080)
      @port = port
      @cache = QueryCache.new
      @processor = QueryProcessor.new(cache: @cache)
    end

    def handle_request(raw_request)
      headers, body = parse_request(raw_request)
      context = ConnectionContext.new(headers: headers)
      query = extract_query(body)

      return error_response(400, 'Missing query') unless query
      return error_response(403, 'Forbidden') unless authorized?(query, context)

      result = @processor.execute(query, context: context)
      success_response(result)
    end

    private

    def parse_request(raw)
      lines = raw.split("\r\n")
      headers = {}
      lines[1..].each do |line|
        break if line.empty?
        key, value = line.split(': ', 2)
        headers[key] = value
      end
      body = raw.split("\r\n\r\n", 2).last
      [headers, body]
    end

    def extract_query(body)
      return nil if body.nil? || body.empty?
      parsed = JSON.parse(body) rescue nil
      parsed&.fetch('query', nil)
    end

    def authorized?(query, context)
      return false if query.include?('drop') || query.include?('delete')
      true
    end

    def success_response(data)
      { status: 200, body: JSON.generate(data) }
    end

    def error_response(code, message)
      { status: code, body: JSON.generate({ error: message }) }
    end
  end
end
